{"version":"v0.9","updateComponents":{"surfaceId":"surface_card","root":"root","components":[{"id":"root","component":"Column","children":["header_row","meter_row","soft_divider","action_button"],"itemMargin":4,"styles":{"width":140,"height":140,"padding":12,"borderRadius":18,"clip":true,"justifyContent":"start","alignItems":"center","linearGradient":{"direction":"RightBottom","colors":[["#46b1e3",0],["#86c5e3",1]]}}},{"id":"header_row","component":"Row","children":["meeting_icon","title_text","status_badge"],"itemMargin":2,"styles":{"width":116,"height":20,"justifyContent":"start","alignItems":"center"}},{"id":"meeting_icon","component":"Image","src":"resources/base/media/icon_meeting.png","styles":{"width":16,"height":16,"objectFit":"contain"}},{"id":"title_text","component":"Text","content":"{{ ${/data/calendar/items/0/title} }}","styles":{"width":50,"height":18,"fontSize":14,"fontWeight":700,"fontColor":"#ffffffff","maxLines":1,"textOverflow":"none","textAlign":"start"}},{"id":"status_badge","component":"Row","children":["status_icon","status_text"],"itemMargin":2,"styles":{"width":46,"height":18,"borderRadius":9,"justifyContent":"center","alignItems":"center","backgroundColor":"#ffffffff"}},{"id":"status_icon","component":"Image","src":"resources/base/media/checkmark_calendar_fill.svg","styles":{"width":10,"height":10,"objectFit":"contain"}},{"id":"status_text","component":"Text","content":"{{ ${/data/calendar/items/0/joinedStatus} }}","styles":{"width":30,"height":12,"fontSize":10,"fontWeight":600,"fontColor":"#ff64bb5c","maxLines":1,"textOverflow":"none","textAlign":"center"}},{"id":"meter_row","component":"Row","children":["countdown_col","countdown_ring"],"itemMargin":6,"styles":{"width":116,"height":50,"justifyContent":"center","alignItems":"center"}},{"id":"countdown_col","component":"Column","children":["primary_row","time_text"],"itemMargin":2,"styles":{"width":68,"height":50,"justifyContent":"center","alignItems":"start"}},{"id":"primary_row","component":"Row","children":["primary_value","primary_unit"],"itemMargin":2,"styles":{"width":68,"height":34,"justifyContent":"start","alignItems":"bottom"}},{"id":"primary_value","component":"Text","content":"{{ ${/data/calendar/items/0/remainingMinutesText} }}","styles":{"width":42,"height":34,"fontSize":32,"fontWeight":800,"fontColor":"#ffffffff","maxLines":1,"textOverflow":"none","textAlign":"start"}},{"id":"primary_unit","component":"Text","content":"分钟","styles":{"width":24,"height":16,"fontSize":12,"fontWeight":600,"fontColor":"#99ffffff","maxLines":1,"textOverflow":"none","textAlign":"start"}},{"id":"time_text","component":"Text","content":"{{ ${/data/calendar/items/0/dtStart} + ' 开始' }}","styles":{"width":68,"height":14,"fontSize":12,"fontWeight":500,"fontColor":"#99ffffff","maxLines":1,"textOverflow":"none","textAlign":"start"}},{"id":"countdown_ring","component":"Progress","value":"{{ ${/data/calendar/items/0/countdownProgress} }}","total":"{{ ${/data/calendar/items/0/countdownTotal} }}","styles":{"width":42,"height":42,"type":"ring","color":"#ffffffff"}},{"id":"soft_divider","component":"Divider","styles":{"width":116,"height":1,"strokeWidth":1,"color":"#66ffffff"}},{"id":"action_button","component":"Button","label":"{{ '导航 ' + ${/data/calendar/items/0/eventLocation} }}","onClick":[{"call":"clickToIntent","args":{"intentName":"StartNavigate","params":{"dstLocation":{"latitude":"{{ ${/data/calendar/items/0/destination/latitude} }}","longitude":"{{ ${/data/calendar/items/0/destination/longitude} }}"},"trafficpe":"Walk"}}}],"styles":{"width":116,"height":33,"borderRadius":16,"fontSize":14,"fontWeight":600,"fontColor":"#e5000000","backgroundColor":"#ffffffff"}}]}}
